// 本域来源完整先验后按真实Common序选择最新当面申请；后续答复不扫描别人私约。
#include "political_office_resignation_director.hpp"
namespace hanmo::resident {
Outcome<PoliticalOfficeResignationResponseKnown> read_political_office_resignation_response_known(const PoliticalOfficeResignationContext& x,const StableId& actor,const PoliticalOfficeResignationResponseIntent& intent){if(!x.responses||x.state.version!=2||x.responses->intents.find(intent.id)!=&intent||actor!=intent.approver_actor_id)return {false,{},common_failure("OfficeResignationResponseKnownSourceRequired").error};auto valid=validate_political_office_resignation_sources(x);if(!valid.ok)return {false,{},valid.error};PoliticalOfficeResignationResponseKnown out{x.common.state().identity,actor,intent.id,{},{},0,0};for(const auto& h:x.common.state().facts.rows()){const auto* r=x.state.requests.find(h.first);if(!r||r->approver_actor_id!=actor||r->policy_id!=intent.resignation_policy_id)continue;out.request_fact_id=r->id;out.request_tick=r->tick;out.response_until=r->response_until;out.own_answer_fact_id.clear();}if(!out.request_fact_id.empty())for(const auto& a:x.state.answers.rows())if(a.second.request_fact_id==out.request_fact_id&&a.second.actor_id==actor)out.own_answer_fact_id=a.first;return {true,std::move(out),{}};}
Outcome<AuthoredOfficeResignationCommand> preview_political_office_resignation_response_local(const PoliticalOfficeResignationContext& x,const StableId& actor,const PoliticalOfficeResignationResponseIntent& intent,const PoliticalOfficeResignationResponseKnown& known){auto current=read_political_office_resignation_response_known(x,actor,intent);if(!current.ok)return {false,{},current.error};const auto& v=current.value;const auto& a=v.identity;const auto& b=known.identity;if(std::tie(v.observer_actor_id,v.intent_id,v.request_fact_id,v.own_answer_fact_id,v.request_tick,v.response_until,a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(known.observer_actor_id,known.intent_id,known.request_fact_id,known.own_answer_fact_id,known.request_tick,known.response_until,b.world_id,b.execution_epoch,b.revision,b.tick)||v.request_fact_id.empty()||!v.own_answer_fact_id.empty())return {false,{},common_failure("OfficeResignationResponseKnowledgeChanged").error};const auto& r=*x.state.requests.find(v.request_fact_id);auto decision=read_political_office_resignation_response_decision(x.common,x.organizations,x.organization_catalog,r,intent,x.common.tick());if(!decision.ok)return {false,{},decision.error};AuthoredOfficeResignationCommand command{{intent.id,intent.director_policy_id,actor,r.id,decision.value.reason},{{r.organization_id,r.approver_office_id,r.approver_epoch,actor},r.id,decision.value.accept}};auto local=x;local.authored_command=&command.origin;auto quoted=preview_political_office_resignation(local,actor,command.command);return quoted.ok?Outcome<AuthoredOfficeResignationCommand>{true,std::move(command),{}}:Outcome<AuthoredOfficeResignationCommand>{false,{},quoted.error};}
}
